package dk.sdu.cbse.gamelab; public final class WeaponComponent implements IGamePluginService,IEntityProcessingService{private long last;public void start(GameData d){}public void stop(GameData d){d.entities.removeIf(e->e.type.equals("BULLET"));}public void process(GameData d,double dt){Entity p=d.entities.stream().filter(e->e.type.equals("PLAYER")).findFirst().orElse(null);long now=System.nanoTime();if(p!=null&&d.keys.contains("FIRE")&&now-last>250_000_000L){double a=Math.toRadians(p.rotation);Entity bullet=new Entity("BULLET",p.x,p.y,3);bullet.owner="PLAYER";bullet.dx=Math.cos(a)*300;bullet.dy=Math.sin(a)*300;d.entities.add(bullet);last=now;}for(Entity x:d.entities.stream().filter(e->e.type.equals("BULLET")).toList()){x.x+=x.dx*dt;x.y+=x.dy*dt;if(x.x<0||x.x>d.width||x.y<0||x.y>d.height)d.entities.remove(x);}}}